function nextTab(n){$(n).next().find('a[data-toggle="tab"]').click()}function prevTab(n){$(n).prev().find('a[data-toggle="tab"]').click()}$(document).ready(function(){$(".nav-tabs > li a[title]").tooltip();$('a[data-toggle="tab"]').on("show.bs.tab",function(n){var t=$(n.target);if(t.parent().hasClass("disabled"))return!1});$(".next-step").click(function(){var n=$(".wizard .nav-tabs li.active");n.next().removeClass("disabled");nextTab(n)});$(".prev-step").click(function(){var n=$(".wizard .nav-tabs li.active");prevTab(n)})});